const list = document.querySelector("#list");

// One listener handles all current and future <li> elements.
list.addEventListener("click", (event) => {
  if (event.target.matches("li")) {
    console.log("Clicked:", event.target.textContent);
  }
});

// Add a new item later
const newItem = document.createElement("li");
newItem.textContent = "Mango";
list.appendChild(newItem);

// The existing listener also handles the new item.

const parent = document.querySelector("#parent");

parent.addEventListener("click", (event) => {
  console.log("target:", event.target);
  console.log("currentTarget:", event.currentTarget);
});

// If a button inside #parent is clicked:
// event.target = the button
// event.currentTarget = #parent

const child = document.querySelector("#child");
const parent = document.querySelector("#parent");

child.addEventListener("click", (event) => {
  event.stopPropagation();
  console.log("Button clicked");
});

parent.addEventListener("click", () => {
  console.log("Parent clicked");
});

