  event.preventDefault();
  console.log("Navigation prevented");
});

// The link's normal navigation is prevented.

const link = document.querySelector("a");

link.addEventListener("click", (event) => {
  // Stops the event from reaching parent elements
  event.stopPropagation();

  // Stops the browser's default navigation
  event.preventDefault();
});

// stopPropagation() -> controls event propagation
// preventDefault()  -> controls default browser behavior
